.mode-toggle {
    padding: 8px 12px;
    background: white;
    border-bottom: 1px solid #e0e0e0;
}

.mode-buttons {
    display: flex;
    gap: 8px;
    margin-bottom: 8px;
}

.mode-btn {
    flex: 1;
    padding: 8px 16px;
    border: none;
    border-radius: 8px;
    background: #f0f0f0;
    cursor: pointer;
    font-size: 14px;
    transition: all 0.2s;
}

.mode-btn:hover {
    background: #e0e0e0;
}

.mode-btn.active {
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    color: white;
}

.sub-mode-selector {
    display: flex;
    gap: 4px;
}

.sub-mode-btn {
    flex: 1;
    padding: 6px 12px;
    border: 1px solid #ddd;
    border-radius: 6px;
    background: white;
    cursor: pointer;
    font-size: 12px;
    transition: all 0.2s;
}

.sub-mode-btn:hover {
    background: #f5f5f5;
}

.sub-mode-btn.active {
    background: #e8f4fd;
    border-color: #2196f3;
    color: #1976d2;
}`, "",{"version":3,"sources":["webpack://./src/components/ModeToggle.css"],"names":[],"mappings":"AAAA,gCAAgC;;AAEhC;IACI,iBAAiB;IACjB,iBAAiB;IACjB,gCAAgC;AACpC;;AAEA;IACI,aAAa;IACb,QAAQ;IACR,kBAAkB;AACtB;;AAEA;IACI,OAAO;IACP,iBAAiB;IACjB,YAAY;IACZ,kBAAkB;IAClB,mBAAmB;IACnB,eAAe;IACf,eAAe;IACf,oBAAoB;AACxB;;AAEA;IACI,mBAAmB;AACvB;;AAEA;IACI,qDAAqD;IACrD,YAAY;AAChB;;AAEA;IACI,aAAa;IACb,QAAQ;AACZ;;AAEA;IACI,OAAO;IACP,iBAAiB;IACjB,sBAAsB;IACtB,kBAAkB;IAClB,iBAAiB;IACjB,eAAe;IACf,eAAe;IACf,oBAAoB;AACxB;;AAEA;IACI,mBAAmB;AACvB;;AAEA;IACI,mBAAmB;IACnB,qBAAqB;IACrB,cAAc;AAClB","sourcesContent":["/* ModeToggle Component Styles */\n\n.mode-toggle {\n    padding: 8px 12px;\n    background: white;\n    border-bottom: 1px solid #e0e0e0;\n}\n\n.mode-buttons {\n    display: flex;\n    gap: 8px;\n    margin-bottom: 8px;\n}\n\n.mode-btn {\n    flex: 1;\n    padding: 8px 16px;\n    border: none;\n    border-radius: 8px;\n    background: #f0f0f0;\n    cursor: pointer;\n    font-size: 14px;\n    transition: all 0.2s;\n}\n\n.mode-btn:hover {\n    background: #e0e0e0;\n}\n\n.mode-btn.active {\n    background: linear-gradient(135deg, #1a1a2e, #16213e);\n    color: white;\n}\n\n.sub-mode-selector {\n    display: flex;\n    gap: 4px;\n}\n\n.sub-mode-btn {\n    flex: 1;\n    padding: 6px 12px;\n    border: 1px solid #ddd;\n    border-radius: 6px;\n    background: white;\n    cursor: pointer;\n    font-size: 12px;\n    transition: all 0.2s;\n}\n\n.sub-mode-btn:hover {\n    background: #f5f5f5;\n}\n\n.sub-mode-btn.active {\n    background: #e8f4fd;\n    border-color: #2196f3;\n    color: #1976d2;\n}"],"sourceRoot":""}]);
