   SETTINGS PANEL
   ============================================ */

.settings-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--bg-primary);
}

/* Settings Header */
.settings-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    padding: var(--space-5) var(--space-5) var(--space-4);
    border-bottom: 1px solid var(--border-light);
}

.settings-header__title {
    font-size: var(--text-lg);
    font-weight: var(--font-semibold);
    color: var(--text-primary);
    letter-spacing: -0.02em;
}

.settings-header__close {
    font-size: var(--text-sm);
    color: var(--text-tertiary);
    transition: color var(--transition-fast);
}

.settings-header__close:hover {
    color: var(--text-primary);
}

/* Settings Content */
.settings-content {
    flex: 1;
    overflow-y: auto;
    padding: var(--space-6) var(--space-5);
}

/* Settings Section */
.settings-section {
    margin-bottom: var(--space-8);
}

.settings-section:last-child {
    margin-bottom: 0;
}

.settings-label {
    display: block;
    font-size: var(--text-xs);
    font-weight: var(--font-normal);
    color: var(--text-tertiary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-3);
}

/* Settings Input */
.settings-input {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    font-size: var(--text-base);
    color: var(--text-primary);
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    outline: none;
    transition: all var(--transition-fast);
}

.settings-input::placeholder {
    color: var(--text-muted);
}

.settings-input:focus {
    background: var(--bg-primary);
    border-color: var(--neutral-400);
}

/* Settings Select */
.settings-select-wrapper {
    position: relative;
}

.settings-select {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    padding-right: var(--space-8);
    font-size: var(--text-base);
    color: var(--text-primary);
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    outline: none;
    appearance: none;
    cursor: pointer;
    transition: all var(--transition-fast);
}

.settings-select:focus {
    background: var(--bg-primary);
    border-color: var(--neutral-400);
}

.settings-select-arrow {
    position: absolute;
    right: var(--space-4);
    top: 50%;
    transform: translateY(-50%);
    font-size: 10px;
    color: var(--text-muted);
    pointer-events: none;
}

/* Label with action */
.settings-label-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: var(--space-3);
}

.settings-label-action {
    font-size: var(--text-xs);
    color: var(--text-muted);
    transition: color var(--transition-fast);
}

.settings-label-action:hover {
    color: var(--text-secondary);
}

/* Provider Toggle */
.settings-toggle-group {
    display: flex;
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    overflow: hidden;
}

.settings-toggle-btn {
    flex: 1;
    padding: 10px var(--space-4);
    font-size: var(--text-base);
    font-weight: var(--font-medium);
    color: var(--text-secondary);
    background: var(--bg-primary);
    border: none;
    transition: all var(--transition-fast);
}

.settings-toggle-btn:not(:last-child) {
    border-right: 1px solid var(--border-light);
}

.settings-toggle-btn:hover:not(.settings-toggle-btn--active) {
    background: var(--bg-secondary);
}

.settings-toggle-btn--active {
    background: var(--bg-dark);
    color: var(--text-inverse);
}

/* Cache Section */
.settings-cache-box {
    padding: var(--space-4);
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
}

.settings-cache-text {
    font-size: var(--text-sm);
    color: var(--text-secondary);
    line-height: 1.5;
    margin-bottom: var(--space-3);
}

.settings-cache-actions {
    display: flex;
    gap: var(--space-2);
}

.settings-cache-btn {
    flex: 1;
    padding: var(--space-2) var(--space-3);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    color: var(--text-secondary);
    background: var(--bg-primary);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    transition: all var(--transition-fast);
}

.settings-cache-btn:hover {
    background: var(--bg-secondary);
}

.settings-cache-btn--danger:hover {
    color: #dc2626;
    border-color: #fecaca;
}

/* Settings Footer */
.settings-footer {
    padding: var(--space-4) var(--space-5);
    border-top: 1px solid var(--border-light);
}

.settings-done-btn {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    font-size: var(--text-base);
    font-weight: var(--font-medium);
    color: var(--text-inverse);
    background: var(--bg-dark);
    border-radius: var(--radius-md);
    transition: background var(--transition-fast);
}

.settings-done-btn:hover {
    background: var(--neutral-800);
