/**
 * Application State Types for Vibe Legal
 * Extracted from vibe-legal-beta-0.2.yaml + 0.3 Pro Mode
 */
export function getRiskLabel(level) {
    if (level <= 33)
        return 'Conservative';
    if (level <= 66)
        return 'Moderate';
    return 'Aggressive';
}
export function getRiskSublabel(level) {
    if (level <= 10)
        return 'Very Conservative';
    if (level <= 25)
        return 'Conservative';
    if (level <= 40)
        return 'Conservative-Moderate';
    if (level <= 60)
        return 'Moderate';
    if (level <= 75)
        return 'Moderate-Aggressive';
    if (level <= 90)
        return 'Aggressive';
    return 'Very Aggressive';
}
export const initialRiskTolerance = {
    enabled: false,
    level: 50,
    bestPosition: '',
    fallbackPosition: ''
};
