lay: block;\n    font-size: 13px;\n    font-weight: 500;\n    color: #374151;\n    margin-bottom: 8px;\n}\n\n.setup-textarea {\n    width: 100%;\n    padding: 10px 12px;\n    border: 1px solid #e5e7eb;\n    border-radius: 8px;\n    font-size: 13px;\n    resize: none;\n    font-family: inherit;\n    box-sizing: border-box;\n}\n\n.setup-textarea:focus {\n    outline: none;\n    border-color: #3b82f6;\n}\n\n.char-count {\n    text-align: right;\n    font-size: 11px;\n    color: #9ca3af;\n    margin-top: 4px;\n}\n\n/* Mode Options */\n.mode-options {\n    display: flex;\n    gap: 10px;\n}\n\n.mode-option {\n    flex: 1;\n    padding: 12px;\n    border: 1px solid #e5e7eb;\n    border-radius: 10px;\n    background: white;\n    cursor: pointer;\n    text-align: center;\n    transition: all 0.2s;\n}\n\n.mode-option:hover {\n    border-color: #d1d5db;\n    background: #f9fafb;\n}\n\n.mode-option.selected {\n    border-color: #3b82f6;\n    background: #eff6ff;\n}\n\n.mode-icon {\n    font-size: 24px;\n    margin-bottom: 6px;\n}\n\n.mode-name {\n    font-weight: 600;\n    font-size: 13px;\n    margin-bottom: 4px;\n}\n\n.mode-desc {\n    font-size: 11px;\n    color: #6b7280;\n}\n\n/* Side Options */\n.side-options {\n    display: flex;\n    gap: 10px;\n}\n\n.side-option {\n    flex: 1;\n    padding: 10px;\n    border: 1px solid #e5e7eb;\n    border-radius: 8px;\n    background: white;\n    cursor: pointer;\n    font-size: 12px;\n    font-weight: 500;\n    transition: all 0.2s;\n}\n\n.side-option.selected {\n    border-color: #10b981;\n    background: #ecfdf5;\n    color: #059669;\n}\n\n/* Start Button */\n.setup-actions {\n    margin-top: 24px;\n}\n\n.start-btn {\n    width: 100%;\n    padding: 12px;\n    background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%);\n    color: white;\n    border: none;\n    border-radius: 10px;\n    font-size: 14px;\n    font-weight: 600;\n    cursor: pointer;\n    transition: opacity 0.2s;\n}\n\n.start-btn:disabled {\n    opacity: 0.5;\n    cursor: not-allowed;\n}\n\n.start-btn:not(:disabled):hover {\n    opacity: 0.9;\n}\n\n/* Header Actions */\n.header-actions {\n    display: flex;\n    gap: 8px;\n    align-items: center;\n}\n\n.reset-btn {\n    font-size: 12px;\n    color: #6b7280;\n    background: none;\n    border: none;\n    cursor: pointer;\n}\n\n.reset-btn:hover {\n    color: #374151;\n}\n\n.stop-btn {\n    font-size: 12px;\n    color: #dc2626;\n    background: #fef2f2;\n    border: 1px solid #fecaca;\n    border-radius: 6px;\n    padding: 4px 10px;\n    cursor: pointer;\n}\n\n.stop-btn:hover {\n    background: #fee2e2;\n}\n\n/* Interactive Input */\n.interactive-input {\n    padding: 12px 16px;\n    border-top: 1px solid #e5e7eb;\n    background: #f9fafb;\n}\n\n.input-label {\n    font-size: 11px;\n    font-weight: 500;\n    color: #6b7280;\n    margin-bottom: 6px;\n}\n\n.input-textarea {\n    width: 100%;\n    padding: 8px 10px;\n    border: 1px solid #e5e7eb;\n    border-radius: 8px;\n    font-size: 13px;\n    resize: none;\n    font-family: inherit;\n    box-sizing: border-box;\n}\n\n.input-textarea:focus {\n    outline: none;\n    border-color: #3b82f6;\n}\n\n.input-textarea:disabled {\n    background: #f3f4f6;\n}\n\n.input-actions {\n    display: flex;\n    justify-content: space-between;\n    margin-top: 8px;\n}\n\n.ai-respond-btn {\n    font-size: 12px;\n    color: #6b7280;\n    background: white;\n    border: 1px solid #e5e7eb;\n    border-radius: 6px;\n    padding: 6px 12px;\n    cursor: pointer;\n}\n\n.ai-respond-btn:hover:not(:disabled) {\n    background: #f9fafb;\n}\n\n.ai-respond-btn:disabled {\n    opacity: 0.5;\n    cursor: not-allowed;\n}\n\n.send-btn {\n    font-size: 12px;\n    color: white;\n    background: #3b82f6;\n    border: none;\n    border-radius: 6px;\n    padding: 6px 16px;\n    cursor: pointer;\n}\n\n.send-btn:hover:not(:disabled) {\n    background: #2563eb;\n}\n\n.send-btn:disabled {\n    opacity: 0.5;\n    cursor: not-allowed;\n}\n\n/* Negotiate Actions */\n.negotiate-actions {\n    display: flex;\n    justify-content: center;\n    gap: 10px;\n    padding: 12px 16px;\n    border-top: 1px solid #e5e7eb;\n    background: white;\n}\n\n.action-btn {\n    font-size: 12px;\n    padding: 8px 16px;\n    border-radius: 8px;\n    cursor: pointer;\n    transition: all 0.2s;\n}\n\n.action-btn:not(.primary) {\n    color: #374151;\n    background: white;\n    border: 1px solid #e5e7eb;\n}\n\n.action-btn:not(.primary):hover {\n    background: #f9fafb;\n}\n\n.action-btn.primary {\n    color: white;\n    background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%);\n    border: none;\n}\n\n.action-btn.primary:hover {\n    opacity: 0.9;\n}\n\n/* Debate View */\n.debate-view {\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n    min-height: 300px;\n}\n\n.debate-position {\n    padding: 12px 16px;\n    background: #f9fafb;\n    border-bottom: 1px solid #e5e7eb;\n}\n\n.position-label {\n    font-size: 10px;\n    text-transform: uppercase;\n    color: #6b7280;\n    letter-spacing: 0.5px;\n}\n\n.position-text {\n    font-size: 13px;\n    font-weight: 500;\n    color: #1f2937;\n    margin: 4px 0;\n}\n\n.mode-badge {\n    font-size: 11px;\n    color: #6b7280;\n}\n\n.debate-messages {\n    flex: 1;\n    overflow-y: auto;\n    padding: 16px;\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n}\n\n/* Debate Bubbles */\n.debate-bubble {\n    max-width: 85%;\n    padding: 12px 14px;\n    border-radius: 12px;\n    animation: bubbleIn 0.3s ease-out;\n}\n\n.debate-bubble.for {\n    background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%);\n    border: 1px solid #a7f3d0;\n    margin-right: auto;\n    border-bottom-left-radius: 4px;\n}\n\n.debate-bubble.against {\n    background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);\n    border: 1px solid #fde68a;\n    margin-left: auto;\n    border-bottom-right-radius: 4px;\n}\n\n.bubble-author {\n    font-size: 10px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n    margin-bottom: 6px;\n    opacity: 0.7;\n}\n\n.bubble-headline {\n    font-weight: 600;\n    font-size: 13px;\n    color: #1f2937;\n    margin-bottom: 4px;\n}\n\n.bubble-explanation {\n    font-size: 12px;\n    color: #374151;\n    line-height: 1.5;\n}\n\n@keyframes bubbleIn {\n    from {\n        opacity: 0;\n        transform: translateY(10px) scale(0.95);\n    }\n\n    to {\n        opacity: 1;\n        transform: translateY(0) scale(1);\n    }\n}\n\n/* Generating Indicator */\n.generating-indicator {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    padding: 12px;\n    color: #6b7280;\n    font-size: 12px;\n}\n\n.generating-indicator .dot {\n    width: 6px;\n    height: 6px;\n    background: #9ca3af;\n    border-radius: 50%;\n    animation: pulse 1.4s ease-in-out infinite;\n}\n\n.generating-indicator .dot:nth-child(2) {\n    animation-delay: 0.2s;\n}\n\n.generating-indicator .dot:nth-child(3) {\n    animation-delay: 0.4s;\n}\n\n@keyframes pulse {\n\n    0%,\n    100% {\n        opacity: 0.4;\n    }\n\n    50% {\n        opacity: 1;\n    }\n}\n\n.debate-empty {\n    text-align: center;\n    color: #9ca3af;\n    padding: 40px;\n    font-size: 13px;\n}"],"sourceRoot":""}]);
