/**
 * InteractiveInput Component
 * Input area for user arguments in interactive brainstorm mode
 */
import React, { useState } from 'react';
export const InteractiveInput = ({ userSide, onSendArgument, onLetAIRespond, disabled }) => {
    const [input, setInput] = useState('');
    const handleSend = () => {
        if (input.trim().length < 5)
            return;
        onSendArgument(input.trim());
        setInput('');
    };
    const handleKeyDown = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSend();
        }
    };
    return (React.createElement("div", { className: "interactive-input" },
        React.createElement("div", { className: "input-label" },
            "Your turn (",
            userSide === 'for' ? 'FOR' : 'AGAINST',
            "):"),
        React.createElement("textarea", { value: input, onChange: (e) => setInput(e.target.value), onKeyDown: handleKeyDown, placeholder: "Type your argument...", disabled: disabled, rows: 2, className: "input-textarea" }),
        React.createElement("div", { className: "input-actions" },
            React.createElement("button", { onClick: onLetAIRespond, disabled: disabled, className: "ai-respond-btn" }, "Let AI help me"),
            React.createElement("button", { onClick: handleSend, disabled: disabled || input.trim().length < 5, className: "send-btn" }, "Send"))));
};
export default InteractiveInput;
