/**
 * NegotiateSetup Component
 * Setup screen for position input and mode selection
 */
import React, { useState } from 'react';
export const NegotiateSetup = ({ onStartAutoDebate, onStartInteractive }) => {
    const [position, setPosition] = useState('');
    const [selectedMode, setSelectedMode] = useState(null);
    const [userSide, setUserSide] = useState('for');
    const canStart = position.trim().length >= 10;
    const handleStart = () => {
        if (!canStart)
            return;
        if (selectedMode === 'auto') {
            onStartAutoDebate(position.trim());
        }
        else if (selectedMode === 'interactive') {
            onStartInteractive(position.trim(), userSide);
        }
    };
    return (React.createElement("div", { className: "modal__content modal__content--padded" },
        React.createElement("div", { className: "modal__section" },
            React.createElement("label", { className: "modal__label" }, "Your Position"),
            React.createElement("textarea", { value: position, onChange: (e) => setPosition(e.target.value), placeholder: "e.g., The indemnity cap should be 100% of the purchase price...", className: "modal__textarea", style: { height: '112px' }, maxLength: 500 })),
        React.createElement("div", { className: "modal__section" },
            React.createElement("label", { className: "modal__label" }, "Mode"),
            React.createElement("div", { className: "modal__toggle-group" },
                React.createElement("button", { className: `modal__toggle-btn ${selectedMode === 'auto' ? 'modal__toggle-btn--active' : ''}`, onClick: () => setSelectedMode('auto') }, "Auto-Debate"),
                React.createElement("button", { className: `modal__toggle-btn ${selectedMode === 'interactive' ? 'modal__toggle-btn--active' : ''}`, onClick: () => setSelectedMode('interactive') }, "Brainstorm"))),
        selectedMode === 'interactive' && (React.createElement("div", { className: "modal__section" },
            React.createElement("label", { className: "modal__label" }, "Your Side"),
            React.createElement("div", { className: "modal__toggle-group" },
                React.createElement("button", { className: `modal__toggle-btn ${userSide === 'for' ? 'modal__toggle-btn--active' : ''}`, onClick: () => setUserSide('for') }, "For"),
                React.createElement("button", { className: `modal__toggle-btn ${userSide === 'against' ? 'modal__toggle-btn--active' : ''}`, onClick: () => setUserSide('against') }, "Against")))),
        React.createElement("button", { className: "modal__action-btn", onClick: handleStart, disabled: !canStart || !selectedMode }, "Start")));
};
export default NegotiateSetup;
