 * Settings Panel Styles
 * Uses panel system from panels.css
 */

/* Override panel width for settings */
.panel-overlay:has(.settings__section) .panel {
    width: 280px;
}

/* Form sections */
.settings__section {
    margin-bottom: var(--space-5, 20px);
}

.settings__section:last-child {
    margin-bottom: 0;
}

.settings__label {
    display: block;
    font-size: var(--text-xs, 12px);
    font-weight: var(--font-medium, 500);
    color: var(--text-tertiary, #71717a);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-2, 8px);
}

.settings__label-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--space-2, 8px);
}

.settings__label-row .settings__label {
    margin-bottom: 0;
}

.settings__refresh {
    font-size: var(--text-xs, 12px);
    color: var(--text-tertiary, #71717a);
    transition: color var(--transition-fast, 0.15s);
}

.settings__refresh:hover {
    color: var(--text-primary, #18181b);
}

/* Input field */
.settings__input {
    width: 100%;
    padding: var(--space-3, 12px) var(--space-3, 12px);
    font-size: var(--text-sm, 14px);
    color: var(--text-primary, #18181b);
    background: var(--bg-secondary, #f4f4f5);
    border: 1px solid var(--border-light, #e4e4e7);
    border-radius: var(--radius-md, 8px);
    outline: none;
    transition: all var(--transition-fast, 0.15s);
    box-sizing: border-box;
}

.settings__input::placeholder {
    color: var(--text-muted, #a1a1aa);
}

.settings__input:focus {
    background: var(--bg-primary, white);
    border-color: var(--neutral-400, #a1a1aa);
}

/* Select dropdown */
.settings__select-wrapper {
    position: relative;
}

.settings__select {
    width: 100%;
    padding: var(--space-3, 12px) var(--space-6, 24px) var(--space-3, 12px) var(--space-3, 12px);
    font-size: var(--text-sm, 14px);
    color: var(--text-primary, #18181b);
    background: var(--bg-secondary, #f4f4f5);
    border: 1px solid var(--border-light, #e4e4e7);
    border-radius: var(--radius-md, 8px);
    outline: none;
    appearance: none;
    cursor: pointer;
    transition: all var(--transition-fast, 0.15s);
}

.settings__select:focus {
    background: var(--bg-primary, white);
    border-color: var(--neutral-400, #a1a1aa);
}

.settings__select-arrow {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 10px;
    color: var(--text-muted, #a1a1aa);
    pointer-events: none;
}

/* Status message */
.settings__status {
    padding: var(--space-3, 12px);
    background: var(--bg-secondary, #f4f4f5);
    border-radius: var(--radius-md, 8px);
    margin-top: var(--space-4, 16px);
}

.settings__status-text {
    font-size: var(--text-sm, 14px);
    color: var(--text-secondary, #52525b);
    text-align: center;
}

/* Footer with save button */
.settings__footer {
    padding: var(--space-4, 16px);
    border-top: 1px solid var(--border-light, #e4e4e7);
    flex-shrink: 0;
}

.settings__save-btn {
    width: 100%;
    padding: var(--space-3, 12px) var(--space-4, 16px);
    font-size: var(--text-sm, 14px);
    font-weight: var(--font-medium, 500);
    color: white;
    background: var(--bg-dark, #18181b);
    border: none;
    border-radius: var(--radius-md, 8px);
    cursor: pointer;
    transition: background var(--transition-fast, 0.15s);
}

.settings__save-btn:hover:not(:disabled) {
    background: var(--neutral-800, #27272a);
}

.settings__save-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}`, "",{"version":3,"sources":["webpack://./src/components/Settings.css"],"names":[],"mappings":"AAAA;;;EAGE;;AAEF,sCAAsC;AACtC;IACI,YAAY;AAChB;;AAEA,kBAAkB;AAClB;IACI,mCAAmC;AACvC;;AAEA;IACI,gBAAgB;AACpB;;AAEA;IACI,cAAc;IACd,+BAA+B;IAC/B,oCAAoC;IACpC,oCAAoC;IACpC,yBAAyB;IACzB,sBAAsB;IACtB,kCAAkC;AACtC;;AAEA;IACI,aAAa;IACb,8BAA8B;IAC9B,mBAAmB;IACnB,kCAAkC;AACtC;;AAEA;IACI,gBAAgB;AACpB;;AAEA;IACI,+BAA+B;IAC/B,oCAAoC;IACpC,+CAA+C;AACnD;;AAEA;IACI,mCAAmC;AACvC;;AAEA,gBAAgB;AAChB;IACI,WAAW;IACX,kDAAkD;IAClD,+BAA+B;IAC/B,mCAAmC;IACnC,wCAAwC;IACxC,8CAA8C;IAC9C,oCAAoC;IACpC,aAAa;IACb,6CAA6C;IAC7C,sBAAsB;AAC1B;;AAEA;IACI,iCAAiC;AACrC;;AAEA;IACI,oCAAoC;IACpC,yCAAyC;AAC7C;;AAEA,oBAAoB;AACpB;IACI,kBAAkB;AACtB;;AAEA;IACI,WAAW;IACX,4FAA4F;IAC5F,+BAA+B;IAC/B,mCAAmC;IACnC,wCAAwC;IACxC,8CAA8C;IAC9C,oCAAoC;IACpC,aAAa;IACb,gBAAgB;IAChB,eAAe;IACf,6CAA6C;AACjD;;AAEA;IACI,oCAAoC;IACpC,yCAAyC;AAC7C;;AAEA;IACI,kBAAkB;IAClB,WAAW;IACX,QAAQ;IACR,2BAA2B;IAC3B,eAAe;IACf,iCAAiC;IACjC,oBAAoB;AACxB;;AAEA,mBAAmB;AACnB;IACI,6BAA6B;IAC7B,wCAAwC;IACxC,oCAAoC;IACpC,gCAAgC;AACpC;;AAEA;IACI,+BAA+B;IAC/B,qCAAqC;IACrC,kBAAkB;AACtB;;AAEA,4BAA4B;AAC5B;IACI,6BAA6B;IAC7B,kDAAkD;IAClD,cAAc;AAClB;;AAEA;IACI,WAAW;IACX,kDAAkD;IAClD,+BAA+B;IAC/B,oCAAoC;IACpC,YAAY;IACZ,mCAAmC;IACnC,YAAY;IACZ,oCAAoC;IACpC,eAAe;IACf,oDAAoD;AACxD;;AAEA;IACI,uCAAuC;AAC3C;;AAEA;IACI,YAAY;IACZ,mBAAmB;AACvB","sourcesContent":["/**\n * Settings Panel Styles\n * Uses panel system from panels.css\n */\n\n/* Override panel width for settings */\n.panel-overlay:has(.settings__section) .panel {\n    width: 280px;\n}\n\n/* Form sections */\n.settings__section {\n    margin-bottom: var(--space-5, 20px);\n}\n\n.settings__section:last-child {\n    margin-bottom: 0;\n}\n\n.settings__label {\n    display: block;\n    font-size: var(--text-xs, 12px);\n    font-weight: var(--font-medium, 500);\n    color: var(--text-tertiary, #71717a);\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n    margin-bottom: var(--space-2, 8px);\n}\n\n.settings_