 * Risk Tolerance Panel Styles
 * Uses modal system from modals.css
 */

/* Button to redirect to Sides selector */
.risk-panel__sides-btn {
    display: block;
    width: 100%;
    padding: 16px;
    margin-bottom: var(--space-6, 24px);
    background: var(--bg-dark, #18181b);
    color: white;
    font-size: var(--text-sm, 14px);
    font-weight: 500;
    border: none;
    border-radius: var(--radius-md, 8px);
    cursor: pointer;
    text-align: center;
    transition: background 0.15s;
}

.risk-panel__sides-btn:hover {
    background: var(--neutral-800, #27272a);
}

/* Side indicator */
.risk-panel__side {
    font-size: var(--text-sm, 14px);
    color: var(--text-secondary, #52525b);
    margin-bottom: var(--space-6, 24px);
    padding: 12px 14px;
    background: var(--bg-secondary, #f4f4f5);
    border-radius: var(--radius-md, 8px);
}

.risk-panel__side strong {
    color: var(--text-primary, #18181b);
}

/* Disabled state */
.risk-panel__disabled {
    opacity: 0.5;
    pointer-events: none;
}

/* Slider section */
.risk-panel__slider-container {
    margin-bottom: var(--space-4, 16px);
}

.risk-panel__slider-labels {
    display: flex;
    justify-content: space-between;
    font-size: var(--text-xs, 12px);
    color: var(--text-secondary, #71717a);
    margin-bottom: 8px;
}

.risk-panel__level {
    font-weight: 600;
    color: var(--text-primary, #18181b);
}

.risk-panel__slider {
    width: 100%;
    height: 6px;
    -webkit-appearance: none;
    appearance: none;
    background: var(--border-light, #e4e4e7);
    border-radius: 3px;
    outline: none;
}

.risk-panel__slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    background: var(--bg-dark, #18181b);
    border-radius: 50%;
    cursor: pointer;
    border: 2px solid white;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.risk-panel__slider::-moz-range-thumb {
    width: 20px;
    height: 20px;
    background: var(--bg-dark, #18181b);
    border-radius: 50%;
    cursor: pointer;
    border: 2px solid white;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.risk-panel__slider:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.risk-panel__badge {
    text-align: center;
    margin-top: 12px;
    font-size: var(--text-sm, 14px);
    font-weight: 500;
    color: var(--text-primary, #18181b);
    padding: 6px 16px;
    background: var(--bg-secondary, #f4f4f5);
    border-radius: 16px;
    display: inline-block;
}

/* Positions section - side by side */
.risk-panel__positions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-4, 16px);
    margin-bottom: var(--space-6, 24px);
}

.risk-panel__position {
    display: flex;
    flex-direction: column;
}

.risk-panel__position .modal__label {
    margin-bottom: var(--space-1, 4px);
}

.risk-panel__position .modal__textarea {
    flex: 1;
    min-height: 100px;
}

/* Hint text */
.risk-panel__hint {
    font-size: var(--text-xs, 12px);
    color: var(--text-muted, #a1a1aa);
    margin-bottom: 8px;
}

/* Guidance box */
.risk-panel__guidance {
    font-size: var(--text-sm, 14px);
    color: var(--text-secondary, #52525b);
    background: var(--bg-secondary, #f4f4f5);
    padding: 14px 16px;
    border-radius: var(--radius-md, 8px);
    line-height: 1.5;
}

/* Responsive - stack on narrow screens */
@media (max-width: 480px) {
    .risk-panel__positions {
        grid-template-columns: 1fr;
    }
}`, "",{"version":3,"sources":["webpack://./src/components/RiskTolerancePanel.css"],"names":[],"mappings":"AAAA;;;EAGE;;AAEF,yCAAyC;AACzC;IACI,cAAc;IACd,WAAW;IACX,aAAa;IACb,mCAAmC;IACnC,mCAAmC;IACnC,YAAY;IACZ,+BAA+B;IAC/B,gBAAgB;IAChB,YAAY;IACZ,oCAAoC;IACpC,eAAe;IACf,kBAAkB;IAClB,4BAA4B;AAChC;;AAEA;IACI,uCAAuC;AAC3C;;AAEA,mBAAmB;AACnB;IACI,+BAA+B;IAC/B,qCAAqC;IACrC,mCAAmC;IACnC,kBAAkB;IAClB,wCAAwC;IACxC,oCAAoC;AACxC;;AAEA;IACI,mCAAmC;AACvC;;AAEA,mBAAmB;AACnB;IACI,YAAY;IACZ,oBAAoB;AACxB;;AAEA,mBAAmB;AACnB;IACI,mCAAmC;AACvC;;AAEA;IACI,aAAa;IACb,8BAA8B;IAC9B,+BAA+B;IAC/B,qCAAqC;IACrC,kBAAkB;AACtB;;AAEA;IACI,gBAAgB;IAChB,mCAAmC;AACvC;;AAEA;IACI,WAAW;IACX,WAAW;IACX,wBAAwB;IACxB,gBAAgB;IAChB,wCAAwC;IACxC,kBAAkB;IAClB,aAAa;AACjB;;AAEA;IACI,wBAAwB;IACxB,gBAAgB;IAChB,WAAW;IACX,YAAY;IACZ,mCAAmC;IACnC,kBAAkB;IAClB,eAAe;IACf,uBAAuB;IACvB,wCAAwC;AAC5C;;AAEA;IACI,WAAW;IACX,YAAY;IACZ,mCAAmC;IACnC,kBAAkB;IAClB,eAAe;IACf,uBAAuB;IACvB,wCAAwC;AAC5C;;AAEA;IACI,YAAY;IACZ,mBAAmB;AACvB;;AAEA;IACI,kBAAkB;IAClB,gBAAgB;IAChB,+BAA+B;IAC/B,gBAAgB;IAChB,mCAAmC;IACnC,iBAAiB;IACjB,wCAAwC;IACxC,mBAAmB;IACnB,qBAAqB;AACzB;;AAEA,qCAAqC;AACrC;IACI,aAAa;IACb,8BAA8B;IAC9B,yBAAyB;IACzB,mCAAmC;AACvC;;AAEA;IACI,aAAa;IACb,sBAAsB;AAC1B;;AAEA;IACI,kCAAkC;AACtC;;AAEA;IACI,OAAO;IACP,iBAAiB;AACrB;;AAEA,cAAc;AACd;IACI,+BAA+B;IAC/B,iCAAiC;IACjC,kBAAkB;AACtB;;AAEA,iBAAiB;AACjB;IACI,+BAA+B;IAC/B,qCAAqC;IACrC,wCAAwC;IACxC,kBAAkB;IAClB,oCAAoC;IACpC,gBAAgB;AACpB;;AAEA,yCAAyC;AACzC;IACI;QACI,0BAA0B;IAC9B;AACJ","sourcesContent":["/**\n * Risk Tolerance Panel Styles\n * Uses modal system from modals.css\n */\n\n/* Button to redirect to Sides selector */\n.risk-panel__sides-btn {\n    display: block;\n    width: 100%;\n    padding: 16px;\n    margin-bottom: var(--space-6, 24px);\n    background: var(--bg-dark, #18181b);\n    color: white;\n    font-size: var(--text-sm, 14px);\n    font-weight: 500;\n    border: none;\n    border-radius: var(--radius-md, 8px);\n    cursor: pointer;\n    text-align: center;\n    transition: 