    font-size: 13px;
    font-weight: 500;
    background: white;
    border: 1px solid #e4e4e7;
    border-radius: 8px;
    cursor: pointer;
    color: #52525b;
}

.mindmap-button:hover:not(:disabled) {
    background: #f4f4f5;
}

.mindmap-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

