.mindmap__subtopics-label {
    font-size: var(--text-xs);
    font-weight: var(--font-normal);
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-3);
}

.mindmap__subtopics {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

/* Sub-topic Card */
.mindmap__subtopic {
    padding: var(--space-4);
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    animation: fadeIn 0.2s ease-out;
}

.mindmap__subtopic-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-2);
    margin-bottom: var(--space-2);
}

.mindmap__subtopic-name {
    font-size: var(--text-base);
    font-weight: var(--font-medium);
    color: var(--text-primary);
}

.mindmap__subtopic-clauses {
    display: flex;
    gap: var(--space-1);
}

.mindmap__subtopic-clause {
    font-size: 10px;
    color: var(--text-muted);
}

.mindmap__subtopic-summary {
    font-size: var(--text-sm);
    color: var(--text-secondary);
    line-height: 1.5;
    margin-bottom: var(--space-3);
}

.mindmap__subtopic-actions {
    display: flex;
    gap: var(--space-3);
}

.mindmap__subtopic-action {
    font-size: var(--text-xs);
    color: var(--text-tertiary);
    transition: color var(--transition-fast);
}

.mindmap__subtopic-action:hover {
    color: var(--text-primary);
}

.mindmap__subtopic-action--muted {
    color: var(--text-muted);
}

.mindmap__subtopic-action--muted:hover {
    color: var(--text-secondary);
}

/* ============================================
   MIND MAP - AI RESPONSE VIEW
   ============================================ */

.mindmap__ai-view {
    padding: var(--space-5);
    animation: fadeIn 0.2s ease-out;
}

.mindmap__ai-context {
    font-size: var(--text-base);
    color: var(--text-secondary);
    margin-bottom: var(--space-4);
}

.mindmap__ai-response {
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    padding: var(--space-4);
    margin-bottom: var(--space-4);
}

.mindmap__ai-response-label {
    font-size: var(--text-xs);
    font-weight: var(--font-medium);
    color: var(--text-tertiary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-3);
}

.mindmap__ai-response-text {
    font-size: var(--text-base);
    color: var(--text-primary);
    line-height: 1.7;
}

.mindmap__ai-response-text p {
    margin-bottom: var(--space-3);
}

.mindmap__ai-response-text p:last-child {
    margin-bottom: 0;
}

.mindmap__ai-response-text strong {
    font-weight: var(--font-semibold);
}

.mindmap__ai-response-text em {
    font-style: italic;
}

.mindmap__ai-response-text br {
    display: block;
    content: "";
    margin-top: var(--space-2);
}

