 * Context Component Styles
 */

.context-popover {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    width: 300px;
    background: white;
    border: 1px solid #e4e4e7;
    border-radius: 12px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
    padding: 16px;
    z-index: 100;
    animation: popover-in 0.15s ease-out;
}

@keyframes popover-in {
    from {
        opacity: 0;
        transform: translateY(-4px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.context-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
}

.context-title {
    font-weight: 600;
    font-size: 14px;
    color: #18181b;
}

.context-close-btn {
    background: none;
    border: none;
    font-size: 18px;
    color: #71717a;
    cursor: pointer;
    padding: 4px 8px;
    line-height: 1;
    border-radius: 4px;
}

.context-close-btn:hover {
    background: #f4f4f5;
    color: #18181b;
}

.context-hint {
    font-size: 12px;
    color: #71717a;
    margin: 0 0 10px 0;
    line-height: 1.4;
}

.context-textarea {
    width: 100%;
    border: 1px solid #e4e4e7;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 13px;
    font-family: inherit;
    resize: none;
    line-height: 1.5;
    box-sizing: border-box;
}

.context-textarea:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.1);
}

.context-textarea::placeholder {
    color: #a1a1aa;
}

.context-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 8px;
}

.context-footer-hint {
    font-size: 11px;
    color: #a1a1aa;
}

.context-char-count {
    font-size: 11px;
    color: #a1a1aa;
}

.context-char-count.near-limit {
    color: #f59e0b;
}

.context-buttons {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 14px;
}

.context-btn-secondary {
    padding: 8px 16px;
    font-size: 13px;
    font-weight: 500;
    border: 1px solid #e4e4e7;
    background: white;
    color: #52525b;
    border-radius: 8px;
    cursor: pointer;
}

.context-btn-secondary:hover {
    background: #f4f4f5;
}

.context-btn-primary {
    padding: 8px 16px;
    font-size: 13px;
    font-weight: 500;
    border: none;
    background: #18181b;
    color: white;
    border-radius: 8px;
    cursor: pointer;
}

.context-btn-primary:hover {
    background: #27272a;
}

/* Active indicator dot */
.active-dot {
    width: 6px;
    height: 6px;
    background: #10b981;
    border-radius: 50%;
    margin-left: 6px;
    display: inline-block;
    animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {

    0%,
    100% {
        opacity: 1;
    }

    50% {
        opacity: 0.5;
    }
}

/* Context button in toolbar */
.context-button {
    position: relative;
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 6px 12px;
    font-size: 13px;
    font-weight: 500;
    background: white;
    border: 1px solid #e4e4e7;
    border-radius: 8px;
    cursor: pointer;
    color: #52525b;
}

.context-button:hover {
    background: #f4f4f5;
}

.context-button.active {
    background: #f0fdf4;
    border-color: #86efac;
    color: #166534;
}

.context-wrapper {
    position: relative;
}`, "",{"version":3,"sources":["webpack://./src/components/Context.css"],"names":[],"mappings":"AAAA;;EAEE;;AAEF;IACI,kBAAkB;IAClB,qBAAqB;IACrB,OAAO;IACP,YAAY;IACZ,iBAAiB;IACjB,yBAAyB;IACzB,mBAAmB;IACnB,0CAA0C;IAC1C,aAAa;IACb,YAAY;IACZ,oCAAoC;AACxC;;AAEA;IACI;QACI,UAAU;QACV,2BAA2B;IAC/B;;IAEA;QACI,UAAU;QACV,wBAAwB;IAC5B;AACJ;;AAEA;IACI,aAAa;IACb,8BAA8B;IAC9B,mBAAmB;IACnB,mBAAmB;AACvB;;AAEA;IACI,gBAAgB;IAChB,eAAe;IACf,cAAc;AAClB;;AAEA;IACI,gBAAgB;IAChB,YAAY;IACZ,eAAe;IACf,cAAc;IACd,eAAe;IACf,gBAAgB;IAChB,cAAc;IACd,kBAAkB;AACtB;;AAEA;IACI,mBAAmB;IACnB,cAAc;AAClB;;AAEA;IACI,eAAe;IACf,cAAc;IACd,kBAAkB;IAClB,gBAAgB;AACpB;;AAEA;IACI,WAAW;IACX,yBAAyB;IACzB,kBAAkB;IAClB,kBAAkB;IAClB,eAAe;IACf,oBAAoB;IACpB,YAAY;IACZ,gBAAgB;IAChB,sBAAsB;AAC1B;;AAEA;IACI,aAAa;IACb,qBAAqB;IACrB,6CAA6C;AACjD;;AAEA;IACI,cAAc;AAClB;;AAEA;IACI,aAAa;IACb,8BAA8B;IAC9B,mBAAmB;IACnB,eAAe;AACnB;;AAEA;IACI,eAAe;IACf,cAAc;AAClB;;AAEA;IACI,eAAe;IACf,cAAc;AAClB;;AAEA;IACI,cAAc;AAClB;;AAEA;IACI,aAAa;IACb,yBAAyB;IACzB,QAAQ;IACR,gBAAgB;AACpB;;AAEA;IACI,iBAAiB;IACjB,eAAe;IACf,gBAAgB;IAChB,yBAAyB;IACzB,iBAAiB;IACjB,cAAc;IACd,kBAAkB;IAClB,eAAe;AACnB;;AAEA;IACI,mBAAmB;AACvB;;AAEA;IACI,iBAAiB;IACjB,eAAe;IACf,gBAAgB;IAChB,YAAY;IACZ,mBAAmB;IACnB,YAAY;IACZ,kBAAkB;IAClB,eAAe;AACnB;;AAEA;IACI,mBAAmB;AACvB;;AAEA,yBAAyB;AACzB;IACI,UAAU;IACV,WAAW;IACX,mBAAmB;IACnB,kBAAkB;IAClB,gBAAgB;IAChB,qBAAqB;IACrB,gCAAgC;AACpC;;AAEA;;IAEI;;QAEI,UAAU;IACd;;IAEA;QACI,YAAY;IAChB;AACJ;;AAEA,8BAA8B;AAC9B;IACI,kBAAkB;IAClB,aAAa;IACb,mBAAmB;IACnB,QAAQ;IACR,iBAAiB;IACjB,eAAe;IACf,gBAAgB;IAChB,iBAAiB;IACjB,yBAAyB;IACzB,kBAAkB;IAClB,eAAe;IACf,cAAc;AAClB;;AAEA;IACI,mBAAmB;AACvB;;AAEA;IACI,mBAAmB;IACnB,qBAAqB;IACrB,cAAc;AAClB;;AAEA;IACI,kBAAkB;AACtB","sourcesContent":["/**\n * Context Component Styles\n */\n\n.context-popover {\n    position: absolute;\n    top: calc(100% + 8px);\n    left: 0;\n    width: 300px;\n    background: white;\n    border: 1px solid #e4e4e7;\n    border-radius: 12px;\n    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);\n    